class Solution:
    def knightProbability(self, n: int, k: int, row: int, column: int) -> float:
        moves = ((1, 2), (1, -2), (2, 1), (2, -1),
                 (-1, 2), (-1, -2), (-2, 1), (-2, -1))
        dp = [[1.0] * n for _ in range(n)]
        for _ in range(k):
            nxt = [[0.0] * n for _ in range(n)]
            for r in range(n):
                for c in range(n):
                    total = 0.0
                    for dr, dc in moves:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n:
                            total += dp[nr][nc]
                    nxt[r][c] = total / 8.0
            dp = nxt
        return dp[row][column]

