#include <stdio.h>
#include <stdlib.h>

double knightProbability(int n, int k, int row, int column) {
    static const int moves[8][2] = {
        {1,2}, {1,-2}, {2,1}, {2,-1},
        {-1,2}, {-1,-2}, {-2,1}, {-2,-1}
    };
    size_t cells = (size_t)n * (size_t)n;
    double *dp = malloc(cells * sizeof(double));
    double *next = malloc(cells * sizeof(double));
    if (!dp || !next) exit(EXIT_FAILURE);

    for (size_t i = 0; i < cells; i++) dp[i] = 1.0;

    for (int step = 0; step < k; step++) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                double total = 0.0;
                for (int m = 0; m < 8; m++) {
                    int nr = r + moves[m][0], nc = c + moves[m][1];
                    if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                        total += dp[nr * n + nc];
                    }
                }
                next[r * n + c] = total / 8.0;
            }
        }
        double *tmp = dp; dp = next; next = tmp;
    }

    double ans = dp[row * n + column];
    free(dp);
    free(next);
    return ans;
}

